{
  "triage": "emergency",
  "department": "急诊科",
  "conditions": [
    {
      "name": "霍乱",
      "evidence_idx": [1],
      "quote": "重型：腹泻数十次或不可计数，重度脱水，少尿、无尿"
    },
    {
      "name": "细菌性痢疾",
      "evidence_idx": [0],
      "quote": "数小时后出现腹痛、腹泻、里急"
    }
  ],
  "preparation": "请立即去急诊科。向医生说明腹泻已3天、每天十几次、尿量很少、口干明显、发晕，并记录大便性状（水样、稀便、黏液脓血便）、有无发热腹痛呕吐、近期饮食饮水及旅行史、是否集体腹泻、正在服用的药物。若出现意识模糊、站不稳、无尿、四肢湿冷、便血或高热，立刻呼叫急救。以上仅为分诊参考，不构成诊断。"
}

{
  "triage": "emergency",
  "department": "急诊科",
  "conditions": [
    {
      "name": "霍乱",
      "evidence_idx": [1],
      "quote": "中型：有典型泻吐症状，腹泻次数多、量大，轻到中度脱水，可有少尿。"
    },
    {
      "name": "霍乱",
      "evidence_idx": [2],
      "quote": "频繁的腹泻和呕吐导致大量水和电解质丢失，患者迅速出现脱水和微循环衰竭。"
    },
    {
      "name": "细菌性痢疾",
      "evidence_idx": [0],
      "quote": "重型：除上述腹泻症状外，出现严重腹胀及中毒性肠麻痹，严重失水可引起外周循环障碍，出现心、肾功能不全。"
    }
  ],
  "preparation": "立即急诊就医，频繁腹泻伴少尿、口干、头晕提示明显脱水及循环受累，不可拖延。就诊前尽量保留新鲜大便样本或拍照供化验。向医生说明：腹泻起病时间、每天次数、大便性状（水样/黏液/脓血）、尿量变化、口干头晕程度、有无呕吐发热、近期饮食与接触史。途中少量多次口服补液盐或淡盐水。若出现意识模糊、四肢冰凉、脉搏细弱、抽搐、无法饮水等情况，立即拨打120。以上不构成诊断。"
}

