  "conditions": [
    {
      "name": "冠状动脉粥样硬化性心脏病",
      "evidence_idx": [0],
      "quote": "就诊时心动过速、低血压、心力衰竭和新出现的二尖瓣反流，提示预后不良，需尽快诊断和处理。"
    }
  ],
  "preparation": "就诊前准备好医保卡和既往病历、心电图等资料。向医生详细描述心慌开始的时间、持续时长、心跳大概频率，以及是否伴有胸痛、胸闷、大汗、头晕等症状（目前无胸痛、无晕厥），并告知既往是否有高血压、糖尿病、心脏病等病史。若出现胸痛、胸闷、大汗、晕厥、呼吸困难或症状持续加重，请立即拨打120或前往急诊科就诊。本结论不构成诊断。"
}

{
  "triage": "clinic",
  "department": "心血管内科",
  "conditions": [
    {"name": "高血压", "evidence_idx": [0], "quote": "阵发性血压升高，伴头痛、心慌、多汗"},
    {"name": "糖尿病", "evidence_idx": [1], "quote": "心慌、出汗，食欲减退、恶心呕吐、口渴多饮或腹痛等糖尿病疑似急危症"}
  ],
  "preparation": "就诊前记录心慌发作的频率、持续时间、诱因及伴随症状（如头痛、多汗、胸痛、意识障碍等），向医生说明是阵发性还是持续性，有无高血压或糖尿病既往史。若出现意识障碍、深大呼吸、呼气有烂苹果味、血压显著升高≥180/110mmHg或持续不缓解的胸痛，请立即拨打急救电话或前往急诊科。以上建议不构成诊断。"
}

